private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int need = 0; // Calculate the number of bytes needed to decode the next character
    if (i >= bb.limit()) {
        throw new IllegalArgumentException("Not enough data in the buffer.");
    } else {
        // Read the next byte to determine the number of bytes to decode
        int nextByte = bb.get(i);
        need = getNextByteCount(nextByte);
        if (need == 0) {
            throw new IllegalArgumentException("Invalid octet: " + nextByte);
        }
    }

    startNew(sb, need); // Initialize a new string buffer with the required capacity

    // Read the next 'need' bytes from the buffer
    for (int j = 0; j < need; j++) {
        byte nextByte = bb.get(i + j);
        // Only use non-null bytes in the new string buffer
        if (nextByte != 0) {
            sb.append((char) nextByte);
        }
    }

    // Return the index to the next unchecked character in the string to decode
    return i + need;
}

// Helper method to calculate the number of bytes needed to decode the next character
private static int getNextByteCount(int nextByte) {
    if (nextByte < 128) {
        return 1;
    } else if (nextByte < 192) {
        return 2;
    } else if (nextByte < 224) {
        return 3;
    } else if (nextByte < 240) {
        return 4;
    } else if (nextByte < 248) {
        return 5;
    } else if (nextByte < 252) {
        return 6;
    } else if (nextByte < 254) {
        return 7;
    } else {
        throw new IllegalArgumentException("Invalid octet: " + nextByte);
    }
}

