        sb.ensureCapacity(need); // Increase the capacity of the string builder
    }
}

private int visitFrameStart(int offset, int numLocal, int numStack) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is null");
    } else if (offset < 0) {
        throw new IllegalArgumentException("offset must be non-negative");
    } else if (numLocal < 0 || numStack < 0) {
        throw new IllegalArgumentException("numLocal and numStack must be non-negative");
    } else if (currentFrame.instructions == null) {
        currentFrame.instructions = new Instruction[numStack];
    } else if (currentFrame.current == null) {
        currentFrame.current = new Frame(numLocal, numStack);
    } else if (offset < currentFrame.offset) {
        throw new IllegalArgumentException("offset must be greater than or equal to current offset");
    }

    int next = currentFrame.offset;
    currentFrame.offset = offset + 1;
    return next;
}

