public void write(byte[] b) throws IOException {
    if (b == null) {
        throw new IllegalArgumentException("The byte array cannot be null");
    }

    int length = b.length;
    if (length > 0) {
        synchronized (this) {
            int written = 0;
            while (written < length) {
                int remaining = length - written;
                int toWrite = Math.min(remaining, buffer.length);
                System.arraycopy(b, written, buffer, 0, toWrite);
                written += toWrite;
                writeBytes(buffer, 0, toWrite);
                buffer = new byte[buffer.length];
            }
        }
    }
}

