public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null; // Type parameter not parameterized
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    List<Class<?>> resolvedArguments = new ArrayList<>();

    for (Type parameterized : actualTypeArguments) {
        if (parameterized instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) parameterized;
            if (wildcardType.getUpperBounds().length == 0) {
                Type[] lowerBounds = wildcardType.get LowerBounds();
                if (lowerBounds.length == 1 && lowerBounds[0] == Object.class) {
                    resolvedArguments.add(targetType); // Use the most specific bound
                } else {
                    return null; // Unable to resolve wildcard type
                }
            } else {
                return null; // Unable to resolve wildcard type
            }
        } else if (parameterized instanceof GenericArrayType) {
            GenericArrayType genericArrayType = (GenericArrayType) parameterized;
            Class<?> componentType = genericArrayType.getGenericComponentType();
            int dimensions = genericArrayType.getGenericArrayDimensions();
            List<Class<?>> typeArguments = new ArrayList<>();
            for (int i = 0; i < dimensions; i++) {
                typeArguments.add(componentType);
            }
            resolvedArguments.addAll(useBoundType(typeArguments, targetType));
        } else {
            Class<?> componentType = parameterized instanceof Class<?> ? (Class<?>) parameterized : null;
            if (componentType != null && componentType != targetType) {
                resolvedArguments.add(useBoundType(componentType, targetType));
                continue; // If the argument matches the bound, we resolve it
            }
            if (componentType == null) {
                resolvedArguments.add(targetType); // In case of list type, which uses Object class by default
            } else {
                return null; // Unable to resolve the type parameter
            }
        }
    }

    return resolvedArguments.toArray(new Class<?>[resolvedArguments.size()]);
}

private static List<Class<?>> useBoundType(List<Class<?>> typeArguments, Class<?> targetType) {
    for (int i =0; i < typeArguments.size(); i++) {
        if (typeArguments.get(i).equals(targetType)) {
            classBoundType(typeArguments);
        }
    }
    return typeArguments;
}

