private static final long FETCH_DATA_DURATION = 1500; // Example duration in milliseconds

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be smaller than end time");
    }
    if (end - start >= FETCH_DATA_DURATION) {
        int splitDelay = end - start - FETCH_DATA_DURATION;
        List<TimeRange> timeRanges = new ArrayList<>();
        // Perform time range splitting here
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION -(splitDelay/2)));
        // Add a small notch at the end to ensure the data is up to date
        timeRanges.add(new TimeRange(end - (splitDelay/2), end));
        return timeRanges;
    } else {
        return Collections.singletonList(new TimeRange(start, end));
    }
}

