private long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket == 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Input values must be positive.");
    }

    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long dayOfYear = (timeBucket % 10000) % 100;

    while (dayOfYear >= dayStep) {
        dayOfYear -= dayStep;
    }

    return (year * 10000) + (month * 100) + (dayOfYear + 1);
}

