    for (Edge edge : this.edges) {
        edgeDestinations.computeIfAbsent(edge.getSource(), key -> new HashSet<>()).add(edge.getDestination());
    }

    // Identify vertices with negative degree
    for (Vertex vertex : this.vertices) {
        if (!edgeDestinations.containsKey(vertex)) {
            visibleVertices.add(vertex);
        }
    }

    return visibleVertices;
}

