/**
 * Split a box along the x axis into two equal boxes.
 * @param box the box to split
 * @return a pair with the two resulting boxes
 */
public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    double halfWidth = box.getWidth() / 2.0;
    Point2D midpoint = new Point2D.Double(box.getX() + halfWidth, box.getY());

    Box2D leftBox = new Box2D(box.getX(), box.getY(), midpoint.getX(), midpoint.getY());
    Box2D rightBox = new Box2D(midpoint.getX(), box.getY(), box.getX() + box.getWidth(), midpoint.getY());

    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }

    // Calculate new capacity to accommodate the additional bytes
    int newCapacity = Math.max(data.length + size, data.length * 2);

    // Ensure the new capacity does not exceed the maximum array size
    if (newCapacity > Integer.MAX_VALUE) {
        throw new OutOfMemoryError("New capacity exceeds maximum array size");
    }

    // Create a new byte array of the new capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the current data to the new array
    System.arraycopy(data, 0, newArray, 0, data.length);

    // Replace the old data array with the new array
    data = newArray;
}

