public static String unescapeJava(String str) throws Exception {
 Charset charset = StandardCharsets.UTF_8;
 StringBuilder output = new StringBuilder();
 int index = 0;
 while (index < str.length()) {
    char currentChar = str.charAt(index);
    if (currentChar == '\\') {
        index++;
        if (index < str.length()) {
            char nextChar = str.charAt(index);
            switch (nextChar) {
                case '\'':
                    output.append('\'');
                    break;
                case '\"':
                    output.append('\"');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 't':
                    output.append('\t');
                    break;
                default:
                    throw new RuntimeException("Invalid escape sequence: " + nextChar);
            }
            index++;
        } else {
            throw new RuntimeException("EOF while parsing escape sequence");
        }
    } else {
        output.append(currentChar);
        index++;
    }
 }
 return output.toString();
}

