/**
 * Reads the size of a UTF-8 string as an unsigned short.
 * @param classFileBuffer the buffer containing the class file.
 * @param offset the offset in the buffer to start reading the size.
 * @return the unsigned short representing the length of the UTF-8 string.
 */
private final short readUnsignedShort(final byte[] classFileBuffer, final int offset) {
    return (short) ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
}

/**
 * Reads the UTF-8 data using a stream-like read method.
 * Assumes a future stream-like Java API/implementation would be available for UTF-8 (and other common encodings) so read are avoided for code simplicity.
 * @param classFileBuffer the buffer containing the class file.
 * @param offset the offset in the buffer to start reading the UTF-8 string.
 * @param readBuffer the buffer to store the read UTF-8 data.
 * @return the number of bytes read.
 */
private final int readUTF8Data(final byte[] classFileBuffer, final int offset, final char[] readBuffer) {
    int pos = offset;
    while (classFileBuffer[pos] != 0) {
        int continuationByte = classFileBuffer[pos] & 0xFF;
        if (continuationByte >= 128) {
            if (continuationByte >= 248) {
                // 4-byte UTF-8 sequence
                readBuffer[pos] = (char) (0x80 | ((continuationByte - 248) & 0x3F));
                readBuffer[pos + 1] = (char) (0x80 | ((continuationByte - 248) >> 6));
                readBuffer[pos + 2] = (char) (0x80 | ((continuationByte - 248) >> 12));
                readBuffer[pos + 3] = (char) (0x80 | ((continuationByte - 248) >> 18));
                pos += 4;
            } else {
                // 3-byte UTF-8 sequence
                readBuffer[pos] = (char) (0x80 | ((continuationByte - 192) & 0x3F));
                readBuffer[pos + 1] = (char) (0x80 | ((continuationByte - 192) >> 6));
                readBuffer[pos + 2] = (char) (0x80 | ((continuationByte - 192) >> 12));
                pos += 3;
            }
        } else {
            // 2-byte UTF-8 sequence
            readBuffer[pos] = (char) (0x80 | (continuationByte & 0x3F));
            pos++;
        }
    }
    return pos - offset;
}

