    GraphPath<V, E> path = new GraphPath<>();
    V currentNode = graph.getVertexSet().iterator().next();
    Node<V> currentNodeNode = graph.getNode(currentNode);

    for (E edge : tour) {
        Edge<V, E> edgeObj = graph.getEdge(currentEdgeNode, edge);
