public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the name and descriptor are not null
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }

    // Iterate through the existing constants to find a match
    for (int i = 0; i < constantPool.size(); i++) {
        Symbol symbol = constantPool.get(i);
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol.getID();
        }
    }

    // Create a new constant with the provided name and descriptor
    Symbol newSymbol = new Symbol(name, descriptor, constantPool.size() + 1);

    // Add the new constant to the constant pool
    constantPool.add(newSymbol);

    return newSymbol.getID();
}

