private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || bucketsByLabel.isEmpty() || labels == null || labels.isEmpty() || minLabel < 0)
        throw new IllegalArgumentException("Input parameters must be non-null and not empty, and minLabel must be non-negative.");

    for (int i = minLabel; i < bucketsByLabel.size(); i++) {
        bucketsByLabel.forEach(bucket -> bucket.removeIf(v -> labels.get(v) != i));
    }

    bucketsByLabel.removeIf(bucket -> bucket.isEmpty());
    labels.clear();

    int maxLabel = 0;
    for (int i = minLabel; i < bucketsByLabel.size(); i++) {
        bucket.forEach(v -> labels.add(v));
        maxLabel = Math.max(maxLabel, v);
    }

    bucketsByLabel.add(bucket::clear);

    bucketsByLabel.removeIf(bucket -> bucket.isEmpty());
    labels.removeIf(v -> v > maxLabel);

    labels.add(labels.size(), maxLabel + 1);
}

