public static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices) {
    if (graph == null || vertices == null || graph.isEmpty() || vertices.size() == 0) {
        throw new IllegalArgumentException("Graph and vertices cannot be null or empty");
    }

    Set<V> remainingVertices = new HashSet<>(vertices);

    for (V vertex : vertices) {
        Set<V> neighbours = graph.neighbors(vertex);
        if (neighbours.size() < vertices.size() - 1) {
            return false;
        }
        remainingVertices.removeAll(neighbours);
    }

    return remainingVertices.isEmpty();
}

