private List<Integer> computeLowerBounds(List<K> keys) {
    // Start with an empty list to store the lower bounds
    List<Integer> lowerBounds = new ArrayList<>();

    // Check if the list of keys is empty
    if (keys.isEmpty()) {
        // If empty, return an empty list of lower bounds
        return lowerBounds;
    }

    // Assume the first key's lower bound is 0
    lowerBounds.add(0);

    // Iterate through the list of keys starting from the second key
    for (int i = 1; i < keys.size(); i++) {
        // For the current key, check how many keys are smaller than it
        int count = 0;
        for (K key : keys) {
            if (key.compareTo(keys.get(i)) < 0) {
                count++;
            }
        }
        // Append the count to the list of lower bounds
        lowerBounds.add(count);
    }

    // Return the computed lower bounds
    return lowerBounds;
}

private void pop(final String descriptor){
    // Check if the descriptor is valid
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a primitive type or a method type
    int typeCheck = 0;
    switch (descriptor.charAt(0)) {
        case 'L': // Class type
            if (descriptor.length() > 1) {
                typeCheck++;
            }
            break;
        case 'J': // Long type
        case 'I': // Integer type
        case 'F': // Float type
        case 'D': // Double type
        case 'Z': // Boolean type
            if (descriptor.length() > 1) {
                typeCheck++;
            }
            break;
        case 'V': // Void type
            break;
        case 'C': // Char type
            if (descriptor.length() > 1) {
                typeCheck++;
            }
            break;
        default:
            throw new IllegalArgumentException("Unknown type descriptor");
    }

    // Check if the description contains the required number of arguments
    if (descriptor.length() - typeCheck < 0) {
        throw new IllegalArgumentException("Descriptor does not contain enough or invalid argument types");
    }

    // Iterate over the descriptor and pop corresponding arguments
    int index = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        if (Character.isLetter(descriptor.charAt(i)) || descriptor.charAt(i) == ';') {
            index++;
        } else {
            // Check if the argument type is valid
            switch (descriptor.charAt(i)) {
                case 'L':
                    if (index + 1 >= descriptor.length()) {
                        throw new IllegalArgumentException("Invalid class type descriptor");
                    }
                    pop(descriptor.substring(description.charAt(i), description.charAt(i + 1)));
                    index += 2;
                    break;
                case 'J':
                    pop(Long.class);
                    index++;
                    break;
                case 'I':
                    pop(Integer.class);
                    index++;
                    break;
                case 'F':
                    pop(Float.class);
                    index++;
                    break;
                case 'D':
                    pop(Double.class);
                    index++;
                    break;
                case 'Z':
                    pop(Boolean.class);
                    index++;
                    break;
                case 'V':
                    index++;
                    break;
                case 'C':
                    pop(Character.class);
                    index++;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor");
            }
        }
    }
}

